interface PillOption<T extends string> {
  value: T;
  label: string;
}

interface PillGroupProps<T extends string> {
  options: PillOption<T>[];
  value: T;
  onChange: (value: T) => void;
  'aria-label': string;
}

function PillGroup<T extends string>({ options, value, onChange, ...props }: PillGroupProps<T>) {
  return (
    <div className="flex flex-wrap gap-2" role="radiogroup" aria-label={props['aria-label']}>
      {options.map((option) => {
        const isActive = option.value === value;
        return (
          <button
            key={option.value}
            type="button"
            role="radio"
            aria-checked={isActive}
            onClick={() => onChange(option.value)}
            className={`px-3.5 py-1.5 rounded-full text-sm font-medium border transition-colors ${
              isActive
                ? 'bg-accent text-accent-foreground border-accent'
                : 'bg-background/40 text-foreground/70 border-border hover:text-foreground hover:border-accent/40'
            }`}
          >
            {option.label}
          </button>
        );
      })}
    </div>
  );
}

export default PillGroup;
